const input = $json;

const clean = (value) => {
  if (value === undefined || value === null) {
    return null;
  }

  const result = String(value).trim();

  return result === ''
    ? null
    : result;
};

const contactId = clean(input.contact_id);

if (!contactId) {
  throw new Error(
    'contact_id es obligatorio'
  );
}

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

if (!uuidPattern.test(contactId)) {
  throw new Error(
    `contact_id no es un UUID válido: ${contactId}`
  );
}

return [
  {
    json: {
      contact_id: contactId
    }
  }
];

const contactResult =
  $('Execute Workflow · CONTACT Get')
    .first()
    .json;

const taskResult =
  $('Execute Workflow · TASK List Pending')
    .first()
    .json;

const appointmentResult =
  $('Execute Workflow · APPOINTMENT List Upcoming')
    .first()
    .json;

if (
  contactResult.status !== 'resolved' ||
  !contactResult.contact?.id
) {
  throw new Error(
    'No se pudo resolver el contacto'
  );
}

const tasks =
  Array.isArray(taskResult.tasks)
    ? taskResult.tasks
    : [];

const appointments =
  Array.isArray(
    appointmentResult.appointments
  )
    ? appointmentResult.appointments
    : [];

const taskSummary =
  taskResult.summary ?? {
    total: tasks.length,
    overdue: 0,
    today: 0,
    upcoming: 0,
    no_due_date: 0
  };

const appointmentSummary =
  appointmentResult.summary ?? {
    total: appointments.length,
    today: 0,
    tomorrow: 0,
    upcoming: 0,
    confirmed: 0,
    scheduled: 0
  };

/*
 * 08 · TASK · List Pending ya devuelve las tareas
 * ordenadas por relevancia temporal.
 */
const attentionTask =
  tasks[0] ?? null;

/*
 * 09 · APPOINTMENT · List Upcoming devuelve
 * las citas ordenadas por start_at ascendente.
 */
const nextAppointment =
  appointments[0] ?? null;

const signals = {
  has_pending_tasks:
    taskSummary.total > 0,

  has_overdue_tasks:
    taskSummary.overdue > 0,

  has_tasks_today:
    taskSummary.today > 0,

  has_upcoming_appointments:
    appointmentSummary.total > 0,

  has_appointment_today:
    appointmentSummary.today > 0
};

return [
  {
    json: {
      status: 'resolved',

      contact: {
        ...contactResult.contact,

        primary_phone:
          contactResult.primary_phone ?? null,

        phones:
          Array.isArray(contactResult.phones)
            ? contactResult.phones
            : []
      },

      tasks: {
        summary: taskSummary,
        attention_task: attentionTask,
        items: tasks
      },

      appointments: {
        summary: appointmentSummary,
        next_appointment: nextAppointment,
        items: appointments
      },

      signals,

      generated_at:
        new Date().toISOString()
    }
  }
];

const input = $json ?? {};

return [
  {
    json: {
      status: 'not_found',
      contact: null,
      primary_phone: null,
      phones: [],
      tasks: {
        summary: {
          total: 0,
          overdue: 0,
          today: 0,
          upcoming: 0,
          no_due_date: 0
        },
        attention_task: null,
        items: []
      },
      appointments: {
        summary: {
          total: 0,
          today: 0,
          tomorrow: 0,
          upcoming: 0,
          confirmed: 0,
          scheduled: 0
        },
        next_appointment: null,
        items: []
      },
      signals: {
        has_pending_tasks: false,
        has_overdue_tasks: false,
        has_tasks_today: false,
        has_upcoming_appointments: false,
        has_appointment_today: false
      },
      generated_at: new Date().toISOString()
    }
  }
];
